from collections.abc import Mapping, Sequence
from typing import List, Tuple


def rank_numeric_fields(records: Sequence[Mapping[str, int]],
                        target: str) -> List[Tuple[str, float]]:
    if (isinstance(records, (str, bytes)) or
            not isinstance(records, Sequence) or len(records) == 0):
        raise ValueError("records must be a non-empty sequence")
    if not isinstance(target, str):
        raise ValueError("target must be a string")

    rows = []
    expected_keys = None
    for record in records:
        if not isinstance(record, Mapping):
            raise ValueError("every record must be a mapping")
        keys = set(record.keys())
        if not keys or any(not isinstance(key, str) for key in keys):
            raise ValueError("record keys must be a non-empty set of strings")
        if expected_keys is None:
            expected_keys = keys
        elif keys != expected_keys:
            raise ValueError("records must have identical fields")
        if any(isinstance(value, bool) or not isinstance(value, int)
               for value in record.values()):
            raise ValueError("record values must be integers")
        rows.append(dict(record))

    if target not in expected_keys:
        raise ValueError("target field is missing")
    labels = {row[target] for row in rows}
    if labels != {0, 1}:
        raise ValueError("target must contain both binary classes")

    ranked = []
    for field in expected_keys - {target}:
        zero_values = [row[field] for row in rows if row[target] == 0]
        one_values = [row[field] for row in rows if row[target] == 1]
        score = abs(sum(one_values) / len(one_values) -
                    sum(zero_values) / len(zero_values))
        ranked.append((field, score))

    ranked.sort(key=lambda item: (item[1], item[0]))
    return ranked

